// Anti-pattern in Legacy OrderFulfillmentService.cs
public InventoryStatus GetInventory(Guid productId)
{
    // Sync-over-async bug causing ThreadPool depletion
    var result = _inventoryClient.GetStockAsync(productId).Result; 
    return result;
}

// AI-Refactored Production Solution (.NET 9 / C# 13)
public async Task<InventoryStatus> GetInventoryAsync(
    Guid productId, 
    CancellationToken cancellationToken = default)
{
    // Non-blocking async awaiting with cancellation propagation and ConfigureAwait(false)
    return await _inventoryClient
        .GetStockAsync(productId, cancellationToken)
        .ConfigureAwait(false);
}

using System;
using Xunit;

public class MemoryLeakReproductionTests
{
    [Fact]
    public void EventPublisher_ShouldNotKeepSubscriberAlive_AfterUnsubscribe()
    {
        var publisher = new TelemetryPublisher();
        WeakReference weakSubscriberRef = CreateAndSubscribe(publisher);

        // Force full GC collection
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();

        // Assert: Before the bug fix, weakSubscriberRef.IsAlive was true (leak).
        // With proper IDisposable cleanup, IsAlive is false.
        Assert.False(weakSubscriberRef.IsAlive, "Memory leak detected: Subscriber was kept alive by publisher event!");
    }

    private static WeakReference CreateAndSubscribe(TelemetryPublisher publisher)
    {
        var subscriber = new HeavySubscriber();
        subscriber.Register(publisher);
        var weakRef = new WeakReference(subscriber);

        // Explicit disposal removes the delegate handler
        subscriber.Dispose();
        return weakRef;
    }
}
